/*
 * DATA ANALYTICS 09 — A/B EXPERIMENT COMPARATOR
 * Original procedural Canvas 2D artwork. No external assets or libraries.
 * One scene, 25 seconds, deterministic seamless loop, responsive 16:9.
 * Interface: draw(ctx, timeInSeconds, width, height).
 * Recommended export: 3840 x 2160, 60 fps, 100,000,000 bit/s.
 * Bitrate must be set in the exporter. Canvas does not encode video.
 */

function draw(ctx, time, width, height) {
  if (!(width > 0 && height > 0)) return;

  const duration = 25;
  const sceneCount = 1;
  const loopT = ((time % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const unit = Math.min(width / 1920, minSide / 1080);
  const TAU = Math.PI * 2;
  const a = (currentScene + sceneProgress) * TAU;

  const white = '#E5EDF2';
  const muted = '#A2B0C4';
  const cyan = '#80D4E2';
  const coral = '#E6A0AD';

  const clamp = (x, min = 0, max = 1) => Math.max(min, Math.min(max, x));
  const lerp = (p, q, s) => p + (q - p) * s;

  // Harmonik periodik yang halus dan terkontrol untuk transisi natural
  const waveA = 0.068 * Math.sin(a) + 0.016 * Math.sin(2 * a + 0.35);
  const waveB = 0.062 * Math.sin(a + 0.85) - 0.022 * Math.sin(2 * a - 0.45);

  const rateA = 0.585 + waveA;
  const rateB = 0.615 + waveB;

  // Rentang interval (error range) yang proporsional secara visual agar batang vertikal terlihat jelas
  const rangeA = 0.082 + 0.010 * (0.5 + 0.5 * Math.cos(a - 0.3));
  const rangeB = 0.072 + 0.010 * (0.5 + 0.5 * Math.sin(a + 0.5));

  const difference = (rateB - rateA) * 100;
  const differenceHue = clamp((difference + 3.5) / 7, 0, 1);
  const differenceColor =
    'rgb(' +
    Math.round(lerp(128, 230, differenceHue)) +
    ',' +
    Math.round(lerp(212, 160, differenceHue)) +
    ',' +
    Math.round(lerp(226, 173, differenceHue)) +
    ')';

  const columns = [
    {
      x: -528,
      key: 'A',
      baseRate: 0.585,
      rate: rateA,
      error: rangeA,
      color: cyan,
      shade: '#387B9C',
      phase: 0
    },
    {
      x: 12,
      key: 'B',
      baseRate: 0.615,
      rate: rateB,
      error: rangeB,
      color: coral,
      shade: '#8E526E',
      phase: 0.85
    }
  ];

  function linear(x1, y1, x2, y2, stops) {
    const g = ctx.createLinearGradient(x1, y1, x2, y2);
    for (let i = 0; i < stops.length; i++) {
      g.addColorStop(stops[i][0], stops[i][1]);
    }
    return g;
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(Math.max(radius, 0), w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.arcTo(x + w, y, x + w, y + r, r);
    ctx.lineTo(x + w, y + h - r);
    ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
    ctx.lineTo(x + r, y + h);
    ctx.arcTo(x, y + h, x, y + h - r, r);
    ctx.lineTo(x, y + r);
    ctx.arcTo(x, y, x + r, y, r);
    ctx.closePath();
  }

  function topRoundedPath(x, y, w, h, radius) {
    const r = Math.min(Math.max(radius, 0), w / 2, h);
    ctx.beginPath();
    ctx.moveTo(x, y + h);
    ctx.lineTo(x, y + r);
    ctx.arcTo(x, y, x + r, y, r);
    ctx.lineTo(x + w - r, y);
    ctx.arcTo(x + w, y, x + w, y + r, r);
    ctx.lineTo(x + w, y + h);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, thickness) {
    if (w <= 0 || h <= 0) return;
    roundedPath(x, y, w, h, r);
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = thickness || 1.5;
      ctx.stroke();
    }
  }

  function barBox(x, y, w, h, r, fill, stroke, thickness) {
    if (w <= 0 || h <= 0) return;
    topRoundedPath(x, y, w, h, r);
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = thickness || 1.5;
      ctx.stroke();
    }
  }

  function dot(x, y, r, fill, stroke, thickness) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = thickness || 1.5;
      ctx.stroke();
    }
  }

  function rule(x1, y1, x2, y2, color, thickness, dash) {
    ctx.save();
    if (dash) ctx.setLineDash(dash);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness || 1.5;
    ctx.stroke();
    ctx.restore();
  }

  function trace(points, color, thickness) {
    if (points.length < 2) return;
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.stroke();
  }

  function label(text, x, y, size, color, weight, align, baseline) {
    ctx.font = (weight || 500) + ' ' + size + 'px Arial, sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = baseline || 'alphabetic';
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
  }

  function sampleWave(u, phase) {
    const historyLag = (1 - u) * 2.1;
    const angle = a - historyLag;
    if (phase === 0) {
      return 0.068 * Math.sin(angle) + 0.016 * Math.sin(2 * angle + 0.35);
    }
    return 0.062 * Math.sin(angle + 0.85) - 0.022 * Math.sin(2 * angle - 0.45);
  }

  // Distribusi sampel seimbang terhadap titik rata-rata (total offset = 0) dan proporsional di dalam rentang RANGE
  const sampleOffsets = [-0.044, 0.028, -0.016, 0.048, -0.034, 0.020, -0.002];

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'transparent';
    ctx.filter = 'none';
    ctx.setLineDash([]);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Latar belakang gradien matte bersih
    ctx.fillStyle = linear(0, 0, width, height, [
      [0, '#0C1422'],
      [0.42, '#242A40'],
      [0.78, '#34313C'],
      [1, '#162735']
    ]);
    ctx.fillRect(0, 0, width, height);

    const scaleFactor = unit * 1.03;
    ctx.translate(width / 2, height / 2 + 26 * scaleFactor);
    ctx.scale(scaleFactor, scaleFactor);

    // Header utama & lencana status
    label('EXPERIMENT ANALYTICS', -570, -380, 18, white, 700, 'left', 'middle');
    box(398, -395, 172, 30, 15, '#2A3B50', '#8094AA', 1.3);
    label('A / B COMPARISON', 484, -379.5, 10, '#C8D7E0', 600, 'center', 'middle');

    // Kontainer utama
    box(
      -570,
      -330,
      1140,
      674,
      26,
      linear(-570, -330, 570, 344, [
        [0, '#29394E'],
        [1, '#1F3045']
      ]),
      '#91A4B9',
      3.5
    );

    // Sub-header kontainer
    label('CONTROLLED COMPARISON', -528, -291, 11, '#B6C5D4', 600, 'left', 'middle');
    label('SHARED SCALE', 528, -291, 10, muted, 600, 'right', 'middle');

    // Kolom Varian A & B
    for (let index = 0; index < columns.length; index++) {
      const col = columns[index];
      const x = col.x;

      // Kartu Varian
      box(x, -254, 516, 444, 17, '#162A3F', '#4F647E', 1.5);

      // Header Kartu Varian
      const badgeX = x + 44;
      const badgeY = -214;
      dot(badgeX, badgeY, 15, col.color);
      label(col.key, badgeX, badgeY + 0.5, 14, '#203147', 700, 'center', 'middle');
      label('VARIANT ' + col.key, x + 72, badgeY + 0.5, 12, '#D6E3E9', 700, 'left', 'middle');

      // Angka Utama Conversion Rate
      label((col.rate * 100).toFixed(1) + '%', x + 28, -154, 34, white, 600, 'left', 'alphabetic');
      label('CONVERSION RATE', x + 29, -131, 9.5, muted, 600, 'left', 'alphabetic');

      // Area Sparkline
      const sparkStartX = x + 276;
      const sparkEndX = x + 484;
      const sparkMidY = -155;
      rule(sparkStartX, sparkMidY, sparkEndX, sparkMidY, '#263B54', 1, [3, 4]);

      const spark = [];
      const sparkSteps = 64;
      for (let i = 0; i <= sparkSteps; i++) {
        const u = i / sparkSteps;
        const px = lerp(sparkStartX, sparkEndX, u);
        const py = sparkMidY - sampleWave(u, col.phase) * 165;
        spark.push([px, py]);
      }
      trace(spark, col.color, 2.5);
      const lastPt = spark[sparkSteps];
      dot(lastPt[0], lastPt[1], 3.4, col.color, '#162A3F', 1.2);

      // Garis pemisah header dan area grafik
      rule(x + 28, -108, x + 488, -108, '#354C66', 1.2);

      // Area Plot Grafik (Grid & Sumbu)
      const plotLeft = x + 64;
      const plotRight = x + 484;
      const baseline = 145;
      const plotHeight = 216;

      for (let j = 0; j < 5; j++) {
        const y = -71 + j * 54;
        rule(plotLeft, y, plotRight, y, '#2B415B', 1);
        label(String(100 - j * 25), x + 46, y, 9.5, muted, 500, 'right', 'middle');
      }

      // Koordinat 3 lajur grafik yang seimbang dan harmonis
      const barCenter = x + 174;
      const samplesCenter = x + 278;
      const rangeX = x + 368;

      const barWidth = 72;
      const barHeight = plotHeight * col.rate;
      const barTop = baseline - barHeight;

      // Lajur 1: Batang Rata-rata (Mean Bar)
      barBox(
        barCenter - barWidth / 2,
        barTop,
        barWidth,
        barHeight,
        8,
        linear(0, barTop, 0, baseline, [
          [0, col.color],
          [1, col.shade]
        ]),
        col.color,
        1.5
      );
      box(barCenter - 24, barTop + 10, 48, 3, 1.5, 'rgba(231, 245, 248, 0.45)');

      // Garis sumbu dasar (Baseline)
      rule(plotLeft, baseline, plotRight, baseline, '#6D849A', 1.5);

      // Lajur 2: Distribusi Sampel (Samples) — bersih tanpa garis putus-putus yang memotong titik
      const sampleSpacing = 10;
      for (let j = 0; j < 7; j++) {
        const microWave = 0.003 * Math.sin(a + j * 0.9 + col.phase);
        const value = col.rate + sampleOffsets[j] + microWave;
        const sx = samplesCenter + (j - 3) * sampleSpacing;
        const sy = baseline - plotHeight * value;
        dot(sx, sy, 3.0, col.color);
      }

      // Lajur 3: Rentang Kepercayaan (Range) — proporsional dengan ruang batang vertikal yang jelas
      const upper = baseline - plotHeight * (col.rate + col.error);
      const lower = baseline - plotHeight * (col.rate - col.error);
      const capHalfWidth = 10.5;

      rule(rangeX, upper, rangeX, lower, '#BACBD6', 2.0);
      rule(rangeX - capHalfWidth, upper, rangeX + capHalfWidth, upper, col.color, 2.5);
      rule(rangeX - capHalfWidth, lower, rangeX + capHalfWidth, lower, col.color, 2.5);
      dot(rangeX, barTop, 4.0, '#E4EEF2', '#162A3F', 1.4);

      // Label kategori sumbu bawah
      label('MEAN', barCenter, 168, 9, muted, 600, 'center', 'middle');
      label('SAMPLES', samplesCenter, 168, 9, muted, 600, 'center', 'middle');
      label('RANGE', rangeX, 168, 9, muted, 600, 'center', 'middle');
    }

    // Panel Bawah: Perbandingan Selisih (Rate Difference)
    box(-528, 214, 1056, 92, 14, '#172A3F', '#4F647E', 1.5);
    label('RATE DIFFERENCE', -500, 240, 10, muted, 600, 'left', 'middle');

    const rounded = Math.round(difference * 10) / 10;
    const signPrefix = rounded > 0 ? '+' : rounded < 0 ? '-' : '±';
    const formattedDiff = signPrefix + Math.abs(rounded).toFixed(1) + ' pp';
    label(formattedDiff, -500, 274, 26, differenceColor, 600, 'left', 'middle');

    // Sumbu Simetris Indikator Selisih (-15 pp hingga +15 pp)
    const start = -148;
    const end = 484;
    const mid = (start + end) / 2;
    const axisY = 252;
    const indicator = start + clamp((difference + 15) / 30, 0, 1) * (end - start);

    rule(start, axisY, end, axisY, '#536980', 2);

    for (let i = 0; i < 5; i++) {
      const tx = start + ((end - start) * i) / 4;
      const isCenter = i === 2;
      const tickHalf = isCenter ? 8 : 5.5;
      rule(tx, axisY - tickHalf, tx, axisY + tickHalf, isCenter ? '#CAD7E0' : '#6C8097', isCenter ? 1.6 : 1.3);
    }

    const span = Math.abs(indicator - mid);
    if (span > 0.5) {
      box(Math.min(mid, indicator), axisY - 3, span, 6, Math.min(3, span / 2), differenceColor);
    }

    dot(mid, axisY, 2.5, '#CAD7E0');
    dot(indicator, axisY, 6.5, differenceColor, '#E2EBF0', 1.6);

    const tickLabelY = 278;
    label('-15', start, tickLabelY, 9.5, muted, 500, 'center', 'middle');
    label('-7.5', (start + mid) / 2, tickLabelY, 9, '#6C8097', 500, 'center', 'middle');
    label('0', mid, tickLabelY, 9.5, '#CAD7E0', 600, 'center', 'middle');
    label('+7.5', (mid + end) / 2, tickLabelY, 9, '#6C8097', 500, 'center', 'middle');
    label('+15', end, tickLabelY, 9.5, muted, 500, 'center', 'middle');
  } finally {
    ctx.restore();
  }
}

draw.duration = 25;
draw.sceneCount = 1;
draw.fps = 60;
draw.exportSettings = Object.freeze({
  width: 3840,
  height: 2160,
  fps: 60,
  targetBitrate: 100000000,
  minimumBitrate: 100000000,
  maximumBitrate: 100000000
});

/*
 * DATA ANALYTICS 10 — AUTOMATED INSIGHT REPORT
 * Original procedural Canvas 2D artwork. No external assets or libraries.
 * One scene, 25 seconds, deterministic seamless loop, responsive 16:9.
 * Interface: draw(ctx, timeInSeconds, width, height).
 * Recommended export: 3840 x 2160, 60 fps, 100,000,000 bit/s.
 * Bitrate must be set in the exporter. Canvas does not encode video.
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(width / 1920, minSide / 1080);
  const TAU = Math.PI * 2;
  const a = (currentScene + sceneProgress) * TAU;
  if (!(width > 0 && height > 0)) return;

  const white = '#E3EEF4';
  const muted = '#9FB4C9';
  const cyan = '#83CEDF';
  const mint = '#A3DFCC';
  const lavender = '#AFBAE7';

  const clamp = (v) => Math.max(0, Math.min(1, v));
  const smooth = (v) => v * v * (3 - 2 * v);
  const smoother = (v) => v * v * v * (v * (v * 6 - 15) + 10);
  const fract = (v) => v - Math.floor(v);

  // Harmonic data values with controlled amplitude for stable, natural motion
  const bases = [0.46, 0.62, 0.56, 0.76, 0.66];
  const values = bases.map(
    (v, i) =>
      v +
      0.055 * Math.sin(a - i * 0.55) +
      0.018 * Math.sin(2 * a + i * 0.65)
  );
  const average = values.reduce((sum, v) => sum + v, 0) / values.length;
  const peak = Math.max(...values);
  const netChange = (values[4] - values[0]) * 100;

  function linear(x1, y1, x2, y2, stops) {
    const g = ctx.createLinearGradient(x1, y1, x2, y2);
    for (let i = 0; i < stops.length; i++) {
      g.addColorStop(stops[i][0], stops[i][1]);
    }
    return g;
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(Math.max(radius, 0), w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.arcTo(x + w, y, x + w, y + r, r);
    ctx.lineTo(x + w, y + h - r);
    ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
    ctx.lineTo(x + r, y + h);
    ctx.arcTo(x, y + h, x, y + h - r, r);
    ctx.lineTo(x, y + r);
    ctx.arcTo(x, y, x + r, y, r);
    ctx.closePath();
  }

  function topRoundedPath(x, y, w, h, radius) {
    const r = Math.min(Math.max(radius, 0), w / 2, h);
    ctx.beginPath();
    ctx.moveTo(x, y + h);
    ctx.lineTo(x, y + r);
    ctx.arcTo(x, y, x + r, y, r);
    ctx.lineTo(x + w - r, y);
    ctx.arcTo(x + w, y, x + w, y + r, r);
    ctx.lineTo(x + w, y + h);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, thickness) {
    roundedPath(x, y, w, h, r);
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = thickness || 1.5;
      ctx.stroke();
    }
  }

  function barShape(x, y, w, h, r, fill, stroke, thickness) {
    topRoundedPath(x, y, w, h, r);
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = thickness || 1.5;
      ctx.stroke();
    }
  }

  function dot(x, y, r, fill, stroke, thickness) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fill();
    }
    if (stroke) {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = thickness || 1.5;
      ctx.stroke();
    }
  }

  function rule(x1, y1, x2, y2, color, thickness) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness || 1.5;
    ctx.stroke();
  }

  function label(text, x, y, size, color, weight, align, baseline) {
    ctx.font = (weight || 500) + ' ' + size + 'px Arial, sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = baseline || 'alphabetic';
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
  }

  function trace(points, color, thickness) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.stroke();
  }

  function visibility(u) {
    return smoother(clamp(u / 0.12)) * smoother(clamp((1 - u) / 0.12));
  }

  function documentPath() {
    ctx.beginPath();
    ctx.moveTo(-426, -370);
    ctx.lineTo(92, -370);
    ctx.lineTo(182, -280);
    ctx.lineTo(182, 362);
    ctx.arcTo(182, 386, 158, 386, 24);
    ctx.lineTo(-426, 386);
    ctx.arcTo(-450, 386, -450, 362, 24);
    ctx.lineTo(-450, -346);
    ctx.arcTo(-450, -370, -426, -370, 24);
    ctx.closePath();
  }

  function checkmark(x, y, progress, color) {
    const p0x = x - 21.5;
    const p0y = y + 0.5;
    const p1x = x - 6.5;
    const p1y = y + 15.5;
    const p2x = x + 21.5;
    const p2y = y - 15.5;

    const first = Math.hypot(p1x - p0x, p1y - p0y);
    const second = Math.hypot(p2x - p1x, p2y - p1y);
    const length = clamp(progress) * (first + second);
    if (length <= 0) return;

    ctx.beginPath();
    ctx.moveTo(p0x, p0y);
    if (length <= first) {
      const u = length / first;
      ctx.lineTo(p0x + (p1x - p0x) * u, p0y + (p1y - p0y) * u);
    } else {
      const u = (length - first) / second;
      ctx.lineTo(p1x, p1y);
      ctx.lineTo(p1x + (p2x - p1x) * u, p1y + (p2y - p1y) * u);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = 4.5;
    ctx.stroke();
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'transparent';
    ctx.filter = 'none';
    ctx.setLineDash([]);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Matte broad linear gradient background
    ctx.fillStyle = linear(0, 0, width, height, [
      [0, '#0D1425'],
      [0.43, '#212C44'],
      [0.78, '#263847'],
      [1, '#0F1E31']
    ]);
    ctx.fillRect(0, 0, width, height);

    // Balanced composition centering across [-450..552] x [-428..386]
    ctx.translate(width / 2 - 51 * unit, height / 2 + 18 * unit);
    ctx.scale(unit * 1.04, unit * 1.04);

    label('AUTOMATED INSIGHT REPORT', -450, -408, 18, white, 700);

    // Document contour with crisp folded corner
    documentPath();
    ctx.fillStyle = linear(-450, -370, 182, 386, [
      [0, '#2A435C'],
      [1, '#1B334A']
    ]);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(92, -370);
    ctx.lineTo(92, -294);
    ctx.arcTo(92, -280, 106, -280, 14);
    ctx.lineTo(182, -280);
    ctx.closePath();
    ctx.fillStyle = '#36536D';
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(92, -370);
    ctx.lineTo(92, -294);
