      const t2 = tLocal * tLocal;
      const t3 = t2 * tLocal;

      const h00 = 2 * t3 - 3 * t2 + 1;
      const h10 = t3 - 2 * t2 + tLocal;
      const h01 = -2 * t3 + 3 * t2;
      const h11 = t3 - t2;

      const px = nodes[i][0] + (nodes[i + 1][0] - nodes[i][0]) * tLocal;
      const py =
        h00 * nodes[i][1] +
        h10 * slopes[i] +
        h01 * nodes[i + 1][1] +
