/*
 * DATA ANALYTICS 07 — CORRELATION HEATMAP MATRIX
 * Original procedural Canvas 2D artwork, without external assets or libraries.
 * 25 seconds, one scene, deterministic seamless loop, responsive 16:9.
 * Interface: draw(ctx, timeInSeconds, width, height).
 * Recommended export: 3840 x 2160, 60 fps, 100,000,000 bit/s.
 * Apply bitrate in the encoder. Canvas does not encode or compress video.
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(width / 1920, minSide / 1080);
  const TAU = Math.PI * 2;
  const a = (currentScene + sceneProgress) * TAU;
  if (!(width > 0 && height > 0)) return;

  const white = '#E4ECF2';
  const muted = '#A1B0C5';
  const gridX = -458;
  const gridY = -213;
  const pitch = 74;
  const cellSize = 64;
  const letters = ['A', 'B', 'C', 'D', 'E', 'F', 'G'];
  const clamp = v => Math.max(0, Math.min(1, v));
  const smooth = v => v * v * (3 - 2 * v);
  const mix = (x, y, u) => x + (y - x) * u;
  const ramp = (v, start, end) => smooth(clamp((v - start) / (end - start)));
  const pairs = [[0, 1], [3, 4], [0, 5], [2, 6], [1, 3]];
  const step = sceneProgress * pairs.length;
  const slot = Math.floor(step);
  const blend = ramp(step - slot, 0.65, 0.95);
  const from = pairs[slot % pairs.length];
  const to = pairs[(slot + 1) % pairs.length];
  const selectedRow = mix(from[0], to[0], blend);
  const selectedCol = mix(from[1], to[1], blend);

  // Normalized factor vectors create a valid symmetric correlation matrix.
  // The diagonal is exactly one; time changes the data, never the cell layout.
  const bases = [[1,0.15,0.10],[0.92,0.26,0.12],[0.78,0.44,0.28],
    [0.18,1,0.08],[-0.30,0.90,0.16],[-0.92,-0.18,0.30],[-0.78,0.21,0.55]];
  const factors = bases.map((v, i) => {
    const x = v[0] + 0.085 * Math.sin(a + i * 0.63);
    const y = v[1] + 0.070 * Math.sin(2 * a - i * 0.47);
    const z = v[2] + 0.055 * Math.cos(a + i * 0.81);
    const length = Math.hypot(x, y, z);
    return [x / length, y / length, z / length];
  });
  const matrix = factors.map((v, r) => factors.map((w, c) =>
    r === c ? 1 : Math.max(-1, Math.min(1, v[0]*w[0] + v[1]*w[1] + v[2]*w[2]))));
  const pairValue = mix(matrix[from[0]][from[1]], matrix[to[0]][to[1]], blend);

  function coefficientColor(value, bright) {
    const stops = bright ? [[174,189,235],[147,204,212],[241,202,178]]
      : [[89,105,165],[77,137,151],[232,180,156]];
    const index = value < 0 ? 0 : 1;
    const u = value < 0 ? value + 1 : value;
    return 'rgb(' + Math.round(mix(stops[index][0], stops[index+1][0], u)) + ','
      + Math.round(mix(stops[index][1], stops[index+1][1], u)) + ','
      + Math.round(mix(stops[index][2], stops[index+1][2], u)) + ')';
  }

  function coefficientText(value, signed) {
    const rounded = Math.round(value * 100) / 100;
    return (signed && rounded > 0 ? '+' : '') + rounded.toFixed(2);
  }

  function linear(x1, y1, x2, y2, stops) {
    const g = ctx.createLinearGradient(x1, y1, x2, y2);
    for (let i = 0; i < stops.length; i++) g.addColorStop(stops[i][0], stops[i][1]);
    return g;
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(Math.max(radius, 0), w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.arcTo(x + w, y, x + w, y + r, r); ctx.lineTo(x + w, y + h - r);
    ctx.arcTo(x + w, y + h, x + w - r, y + h, r); ctx.lineTo(x + r, y + h);
    ctx.arcTo(x, y + h, x, y + h - r, r); ctx.lineTo(x, y + r);
    ctx.arcTo(x, y, x + r, y, r); ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, thickness) {
    roundedPath(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = thickness || 1.5; ctx.stroke(); }
  }

  function dot(x, y, r, fill, stroke, thickness) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = thickness || 1.5; ctx.stroke(); }
  }

  function rule(x1, y1, x2, y2, color, thickness) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = thickness || 1.5; ctx.stroke();
  }

  function label(text, x, y, size, color, weight, align) {
    ctx.font = (weight || 500) + ' ' + size + 'px Arial, sans-serif';
    ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = color; ctx.fillText(text, x, y);
  }

  function focusFrame(pair, opacity) {
    ctx.save(); ctx.globalAlpha = opacity;
    box(gridX + pair[1] * pitch - 3, gridY + pair[0] * pitch - 3,
      cellSize + 6, cellSize + 6, 11, null, '#E4ECF2', 2);
    ctx.restore();
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'transparent'; ctx.filter = 'none';
    ctx.setLineDash([]); ctx.lineCap = 'round'; ctx.lineJoin = 'round';

    // Matte broad gradient only: no background glow, bloom or blur.
    ctx.fillStyle = linear(0, 0, width, height, [
      [0,'#0C1220'],[0.43,'#252A3E'],[0.78,'#20353F'],[1,'#101C2B']
    ]);
    ctx.fillRect(0, 0, width, height);
    ctx.translate(width / 2, height / 2 + 8 * unit);
    ctx.scale(unit * 1.05, unit * 1.05);

    label('RELATIONSHIP ANALYSIS', -548, -378, 18, white, 700);
    box(-548, -338, 688, 686, 25,
      linear(-548,-338,140,348,[[0,'#293C50'],[1,'#203348']]), '#849BAE', 3.5);
    label('CORRELATION MATRIX', -513, -296, 16, white, 700);
    label('7 x 7', 106, -297, 11, muted, 600, 'right');
    rule(-514, -273, 106, -273, '#46566D', 1.2);

    for (let i = 0; i < 7; i++) {
      label(letters[i], gridX + i * pitch + cellSize / 2, -236, 12.5,
        '#C7D4E1', 600, 'center');
      label(letters[i], -488, gridY + i * pitch + 37, 12.5,
        '#C7D4E1', 600, 'center');
    }

    for (let r = 0; r < 7; r++) {
      for (let c = 0; c < 7; c++) {
        const x = gridX + c * pitch;
        const y = gridY + r * pitch;
        const value = matrix[r][c];
        const active = ((r === from[0] || c === from[1]) ? 1-blend : 0)
          + ((r === to[0] || c === to[1]) ? blend : 0);
        const border = 'rgb(' + Math.round(mix(36,175,active)) + ','
          + Math.round(mix(57,190,active)) + ',' + Math.round(mix(77,201,active)) + ')';
        box(x, y, cellSize, cellSize, 9, coefficientColor(value), border, 1.3);
        label(coefficientText(value, false), x + cellSize / 2, y + 37, 13.5,
          value > 0.55 ? '#25394A' : '#ECF1F4', 600, 'center');
      }
    }

    // Focus borders fade only in the clear gutters around fixed cells.
    // Exterior row/column pointers slide smoothly without covering data.
    focusFrame(from, 1 - blend);
    focusFrame(to, blend);
    box(-518, gridY + selectedRow * pitch + 30, 10, 4, 2, '#D7E4EB');
    box(gridX + selectedCol * pitch + 27, -255, 10, 3.5, 1.75, '#D7E4EB');

    box(202, -288, 350, 636, 21,
      linear(202,-288,552,348,[[0,'#2B3D52'],[1,'#1D3248']]), '#849BAE', 3);
    label('PAIR INSIGHT', 228, -254, 12, '#C9D7E2', 700);
    rule(228, -232, 526, -232, '#46566D', 1.2);
    label('VARIABLES', 228, -201, 10, muted, 600);
    const named = blend < 0.5 ? from : to;
    ctx.save(); ctx.globalAlpha = Math.pow(2 * blend - 1, 2);
    label(letters[named[0]] + '  /  ' + letters[named[1]], 227, -157, 35, white, 600);
    ctx.restore();
    label(coefficientText(pairValue, true), 228, -108,
      31, coefficientColor(pairValue, true), 600);
    label('CORRELATION', 228, -83, 10, muted, 600);
    rule(228, -59, 526, -59, '#46566D', 1.2);
    label('ROW PROFILE', 228, -27, 10, muted, 600);

    const baseline = 56;
    rule(228, baseline, 526, baseline, '#64798E', 1.2);
    for (let i = 0; i < 7; i++) {
      const x = 235 + i * 42;
      const value = mix(matrix[from[0]][i], matrix[to[0]][i], blend);
      const height = Math.max(0.4, Math.abs(value) * 43);
      box(x, value >= 0 ? baseline - height : baseline + 1.5,
        21, height, Math.min(3, height / 2), coefficientColor(value));
      label(letters[i], x + 10.5, 124, 10, muted, 600, 'center');
    }

    label('COEFFICIENT SCALE', 228, 162, 10, muted, 600);
    box(228, 180, 298, 12, 4,
      linear(228,180,526,180,[[0,'#5969A5'],[0.5,'#4D8997'],[1,'#E8B49C']]));
    const scaleX = 228 + clamp((pairValue + 1) / 2) * 298;
    ctx.beginPath(); ctx.moveTo(scaleX, 175); ctx.lineTo(scaleX - 4, 169);
    ctx.lineTo(scaleX + 4, 169); ctx.closePath();
    ctx.fillStyle = '#DAE6EC'; ctx.fill();
    label('-1', 228, 211, 10, muted, 500);
    label('0', 377, 211, 10, muted, 500, 'center');
    label('+1', 526, 211, 10, muted, 500, 'right');
    rule(228, 236, 526, 236, '#46566D', 1.2);
    label('VARIABLES', 228, 261, 10, muted, 600);
    label('07', 526, 262, 14, '#D6E2EA', 600, 'right');
    label('MATRIX CELLS', 228, 287, 10, muted, 600);
    label('49', 526, 288, 14, '#D6E2EA', 600, 'right');
    dot(232, 320, 3.2, '#94D2C6');
    label('SYMMETRIC', 247, 324, 9.5, muted, 600);
  } finally {
    ctx.restore();
  }
}

