  const nowX = 42;
  const right = 474;
  const plotTop = -215;
  const plotBottom = 183;
  const historySpan = nowX - left;
  const futureSpan = right - nowX;
  const nowY = -33 + 9 * Math.sin(a);
  const clamp = x => Math.max(0, Math.min(1, x));

  function history(u) {
    const envelope = Math.pow(Math.sin(Math.PI * u), 2);
    return nowY + 180 * (1 - u) - 20 * Math.pow(1 - u, 2)
      + 14 * envelope * Math.sin(TAU * u - a)
      + 5 * envelope * Math.sin(2 * TAU * u + 2 * a);
  }

  function prediction(u) {
    const envelope = Math.pow(Math.sin(Math.PI * u), 2);
    return nowY - 180 / historySpan * futureSpan * u
      + (56 + 12 * Math.sin(a + 0.6)) * u * u
      + 12 * envelope * Math.sin(TAU * u + a);
  }

  function uncertainty(u) {
    return 5 + 46 * Math.pow(u, 1.2) + 6 * Math.sin(a + 0.3) * u;
  }

  function curvePoint(u) {
    const x = left + (right - left) * clamp(u);
    return x <= nowX ? [x, history((x - left) / historySpan)]
      : [x, prediction((x - nowX) / futureSpan)];
