    label('OBSERVED', -437, -283, 10.5, muted, 600);
    ctx.save(); ctx.setLineDash([6, 5]);
    rule(-106, -287, -78, -287, amber, 2.8); ctx.restore();
    label('PREDICTION', -63, -283, 10.5, muted, 600);
    box(298, -294, 18, 12, 3, '#735E49', '#D2AE7F', 1);
    label('MODEL RANGE', 330, -283, 10.5, muted, 600);
    rule(-526, -257, 526, -257, '#3A5169', 1.3);

    for (let i = 0; i < 5; i++) {
      const y = plotTop + (plotBottom - plotTop) * i / 4;
