    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = thickness;
    ctx.stroke();
  }

  // Three separated groups. Their regular minimum spacing is retained even
  // at the extremes of the small periodic sample movements.
  const samples = [];
  for (let g = 0; g < groups.length; g++) {
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 4; col++) {
        const i = g * 12 + row * 4 + col;
        const x = groups[g].x + (col - 1.5) * 26
          + 4.8 * Math.sin(i * 2.37 + 0.3)
          + 1.6 * Math.sin(2 * a + i * 0.53);
        const y = groups[g].y + (row - 1) * 25
          + 4.2 * Math.cos(i * 1.79 + 0.4)
          + 1.4 * Math.cos(2 * a + i * 0.37);
        samples.push({ x: x, y: y, group: g });
      }
    }
  }

  // The correlation indicator is calculated from the actual animated points.
  let sumX = 0;
  let sumY = 0;
  for (let i = 0; i < samples.length; i++) {
    sumX += samples[i].x;
    sumY -= samples[i].y;
  }
  const meanX = sumX / samples.length;
  const meanY = sumY / samples.length;
  let covariance = 0;
  let spreadX = 0;
  let spreadY = 0;
  for (let i = 0; i < samples.length; i++) {
    const dx = samples[i].x - meanX;
    const dy = -samples[i].y - meanY;
    covariance += dx * dy;
    spreadX += dx * dx;
    spreadY += dy * dy;
  }
  const correlation = covariance / Math.sqrt(spreadX * spreadY);
  let nearestDistance = Infinity;
  for (let g = 0; g < groups.length; g++) {
    const dx = centerX - groups[g].x;
    const dy = centerY - groups[g].y;
    nearestDistance = Math.min(nearestDistance, dx * dx + dy * dy);
  }
  const focusQuality = 0.75 + 0.22 * Math.exp(-nearestDistance / (110 * 110));

  function bracket(x, y, w, h, color, opacity) {
    const length = 12;
    ctx.save();
    ctx.globalAlpha *= opacity;
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(x, y + length);
    ctx.lineTo(x, y);
    ctx.lineTo(x + length, y);
    ctx.moveTo(x + w - length, y);
    ctx.lineTo(x + w, y);
    ctx.lineTo(x + w, y + length);
    ctx.moveTo(x + w, y + h - length);
    ctx.lineTo(x + w, y + h);
    ctx.lineTo(x + w - length, y + h);
    ctx.moveTo(x + length, y + h);
    ctx.lineTo(x, y + h);
    ctx.lineTo(x, y + h - length);
    ctx.stroke();
    ctx.restore();
  }

  function plot(detail) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(-514, -258, 756, 490);
    ctx.clip();
    for (let i = 0; i <= 6; i++) {
      const x = -514 + i * 126;
      rule(x, -258, x, 232, '#2A3C50', 1);
    }
    for (let i = 0; i <= 5; i++) {
      const y = -258 + i * 98;
      rule(-514, y, 242, y, '#2A3C50', 1);
    }

    // The dash period divides the full-loop offset exactly.
    ctx.save();
    ctx.setLineDash([8, 8]);
    ctx.lineDashOffset = -48 * sceneProgress;
    rule(-484, 176, 218, -215, detail ? '#A1DACA' : '#5F9A9C', detail ? 1.8 : 1.7);
    ctx.restore();

    for (let i = 0; i < samples.length; i++) {
      const point = samples[i];
      const dx = point.x - centerX;
      const dy = point.y - centerY;
      const activation = Math.exp(-(dx * dx + dy * dy) / (115 * 115));
      dot(point.x, point.y, 4.6 + activation * 0.7,
        groups[point.group].color, '#122739', detail ? 1.3 : 1.4);
    }

    if (detail) {
      for (let g = 0; g < groups.length; g++) {
        const dx = groups[g].x - centerX;
        const dy = groups[g].y - centerY;
        const active = Math.exp(-(dx * dx + dy * dy) / (105 * 105));
        bracket(groups[g].x - 55, groups[g].y - 42,
          110, 84, groups[g].color, 0.16 + 0.70 * active);
      }
    }
    ctx.restore();
  }

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'transparent';
    ctx.setLineDash([]);
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';

    // Matte contemporary background, using only a broad linear gradient.
    ctx.fillStyle = linear(0, height * 0.08, width, height, [
      [0, '#0A1120'], [0.43, '#1B2138'], [0.8, '#132C37'], [1, '#0B1925']
    ]);
    ctx.fillRect(0, 0, width, height);
    ctx.translate(width / 2, height / 2 + 8 * unit);
    ctx.scale(unit * 1.04, unit * 1.04);

    // One analytic field, with a clearly attached compact findings module.
    box(-558, -348, 848, 652, 28,
      linear(-558, -348, 290, 304, [[0, '#21374C'], [1, '#182E41']]),
      '#819EAF', 3.8);
    box(-535, -326, 802, 607, 14, '#102033', '#3C556A', 1.6);

    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 2; col++) {
        dot(-513 + col * 10, -311 + row * 10, 2.4,
          row === col ? cyan : lavender);
      }
    }
    label('DATA EXPLORER', -481, -301, 17, white, 700);
    label('36 SAMPLES', 242, -302, 11, muted, 600, 'right');
    rule(-514, -282, 242, -282, '#33495F', 1.3);

    plot(false);
    for (let i = 0; i < 3; i++) {
      const x = -514 + i * 109;
      dot(x + 1, 264, 3.6, groups[i].color);
      label('GROUP 0' + (i + 1), x + 12, 268, 9.5, muted, 600);
    }

    // The handle is drawn behind the circular rim. Its rigid attachment and
    // angle are maintained through the complete closed scanning path.
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(Math.PI / 4);
    box(143, -23, 191, 46, 20,
      linear(143, -23, 334, 23, [[0, '#294B5D'], [1, '#387184']]),
      '#A5C5CE', 3.5);
    rule(177, -18, 177, 18, '#8FB7C4', 2.2);
    rule(305, -16, 305, 16, '#75A4B3', 2);
    ctx.restore();

    dot(centerX, centerY, lensRadius, '#1C394B', '#B7D3DB', 4);
    dot(centerX, centerY, 151, '#101F31', '#5EA4B3', 1.5);

    // Actual 2D magnification of exactly the same live plot, clipped to the
    // circular aperture. This is deliberate lens occlusion, not a collision.
    ctx.save();
    ctx.beginPath();
    ctx.arc(centerX, centerY, lensInner, 0, TAU);
    ctx.clip();
    ctx.fillStyle = '#14283A';
    ctx.fillRect(centerX - lensInner, centerY - lensInner,
      lensInner * 2, lensInner * 2);
    ctx.translate(centerX, centerY);
    ctx.scale(magnification, magnification);
    ctx.translate(-centerX, -centerY);
    plot(true);
    ctx.restore();

    ctx.beginPath();
    ctx.arc(centerX, centerY, 154.6,
      -Math.PI * 0.89 + 0.15 * Math.sin(a),
      -Math.PI * 0.50 + 0.15 * Math.sin(a));
    ctx.strokeStyle = '#D0E9E8';
    ctx.lineWidth = 2.2;
    ctx.stroke();

    // Small bridge makes the insight module part of the primary icon.
    box(290, -167, 34, 10, 5, '#315263');
    dot(297 + 18 * (0.5 - 0.5 * Math.cos(4 * a)), -162, 2.3, cyan);
    box(320, -232, 236, 372, 19,
      linear(320, -232, 556, 140, [[0, '#223B50'], [1, '#162E42']]),
      '#819EAF', 3);

    label('INSIGHT', 343, -198, 12, '#BACED7', 700);
    dot(530, -203, 3.5, cyan);
    label('CORRELATION', 343, -164, 10, muted, 600);
    label(correlation.toFixed(2), 342, -117, 42, white, 600);
    label('STRONG RELATIONSHIP', 343, -92, 9.5, cyan, 600);
    rule(343, -73, 532, -73, '#395467', 1.2);

    const spark = [];
    for (let i = 0; i <= 48; i++) {
      const u = i / 48;
      spark.push([343 + 188 * u,
        -18 - 23 * u + 5 * Math.sin(u * TAU * 1.3 - 2 * a)
        + 2 * Math.sin(u * TAU * 2 + 2 * a)]);
    }
    rule(343, -7, 531, -7, '#365063', 1);
    trace(spark, lavender, 2.5);
    dot(spark[48][0], spark[48][1], 3, lavender);

    label('FOCUS QUALITY', 343, 32, 9.5, muted, 600);
    label((focusQuality * 100).toFixed(0) + '%', 531, 32,
      11, white, 600, 'right');
    box(343, 47, 188, 7, 3.5, '#355165');
    box(343, 47, 188 * focusQuality, 7, 3.5, cyan);
    rule(343, 79, 532, 79, '#395467', 1.2);
    dot(350, 108, 7, '#294C58', cyan, 1.1);
    ctx.beginPath();
    ctx.moveTo(346.7, 108);
    ctx.lineTo(349.1, 110.4);
    ctx.lineTo(353.6, 105.4);
    ctx.strokeStyle = '#B9E8D9';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    label('PATTERN VERIFIED', 367, 111.5, 9.5, '#BAD2DA', 600);
  } finally {
    ctx.restore();
  }
}

draw.duration = 25;
draw.sceneCount = 1;
draw.fps = 60;
draw.exportSettings = Object.freeze({
  width: 3840,
  height: 2160,
  fps: 60,
  targetBitrate: 100000000,
  minimumBitrate: 100000000,
  maximumBitrate: 100000000
});
